<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\Accessor\TrustedClientTlsClientCertificateBoundAccessTokensAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TrustedClientTlsClientCertificateBoundAccessTokensAccessor trait.
 *
 * Covers null default, string/VO assignment via withTlsClientCertificateBoundAccessTokens,
 * getTlsClientCertificateBoundAccessTokens/tlsClientCertificateBoundAccessTokens accessors, and isTlsClientCertificateBoundAccessTokensChanged with/without original.
 */
class TrustedClientTlsClientCertificateBoundAccessTokensAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withTlsClientCertificateBoundAccessTokens creates a new instance with the TlsClientCertificateBoundAccessTokens set
     * from a string value, and getTlsClientCertificateBoundAccessTokens returns the primitive string.
     */
    public function testWithTlsClientCertificateBoundAccessTokensFromString(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientTlsClientCertificateBoundAccessTokensAccessorUnitTest();

        // Act
        $result = $holder->withTlsClientCertificateBoundAccessTokens(true);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(true, $result->isTlsClientCertificateBoundAccessTokens());
    }
    /**
     * Asserts that withtlsClientCertificateBoundAccessTokens has access to the value object
     * from a string value, and getTlsClientCertificateBoundAccessTokens returns the primitive string.
     */
    public function testWithTlsClientCertificateBoundAccessTokensFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientTlsClientCertificateBoundAccessTokensAccessorUnitTest();

        // Act
        $result = $holder->withTlsClientCertificateBoundAccessTokens(true);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(true, $result->tlsClientCertificateBoundAccessTokens()->value());
    }
    public function testChangedTlsClientCertificateBoundAccessTokens(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientTlsClientCertificateBoundAccessTokensAccessorUnitTest()->withTlsClientCertificateBoundAccessTokens(true);
        $original = $holder->withTlsClientCertificateBoundAccessTokens(true);
        $same = $holder->withTlsClientCertificateBoundAccessTokens(true);
        $modified = $holder->withTlsClientCertificateBoundAccessTokens(false);

        // Act
        $withSame = $original->isTlsClientCertificateBoundAccessTokensChanged($same);
        $withDiferent = $original->isTlsClientCertificateBoundAccessTokensChanged($modified);

        // Assert
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithTrustedClientTlsClientCertificateBoundAccessTokensAccessorUnitTest
{
    use TrustedClientTlsClientCertificateBoundAccessTokensAccessor;
}
